// Step 1: Define a parameter (created via Manage Parameters UI)
// Power BI creates this automatically in the background:
ServerName = "PROD-SQL01" meta [IsParameterQuery = true, Type = type text]

// Step 2: Reference the parameter in a query
let
    Source = Sql.Database(ServerName, DatabaseName),
    Sales = Source{[Schema="dbo",Item="Sales"]}[Data],
    FilteredRows = Table.SelectRows(Sales, each [OrderDate] >= StartDate)
in
    FilteredRows

